package com.bank.batch;

import java.util.logging.Logger;

public class FileNameMatcher {

    private static final Logger log = Logger.getLogger(FileNameMatcher.class.getName());

    public boolean isMatch(String s, String p) {
        int m = s.length(), n = p.length();
        boolean[][] dp = new boolean[m + 1][n + 1];
        dp[0][0] = true;                               // empty matches empty
        for (int j = 1; j <= n; j++) {                 // leading stars match empty text
            if (p.charAt(j - 1) == '*') dp[0][j] = dp[0][j - 1];
        }
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                char pc = p.charAt(j - 1);
                if (pc == '*') {
                    dp[i][j] = dp[i - 1][j]            // star absorbs one more text char
                            || dp[i][j - 1];           // star matches empty
                } else if (pc == '?' || pc == s.charAt(i - 1)) {
                    dp[i][j] = dp[i - 1][j - 1];        // single char match
                }
            }
        }
        boolean result = dp[m][n];
        log.info(() -> "isMatch(" + s + "," + p + ") = " + result);
        return result;
    }
}
