package com.bank.batch;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class WildcardDemo {

    private static final Logger log = Logger.getLogger(WildcardDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — File Name Matcher (Wildcard Matching)");
        FileNameMatcher matcher = new FileNameMatcher();
        log.info("'adceb' vs '*a*b' → " + matcher.isMatch("adceb", "*a*b")); // true
        log.info("'acdcb' vs 'a*c?b' → " + matcher.isMatch("acdcb", "a*c?b")); // false
    }
}
